        if s[i]==s[i-1] and i!=n-1:
            ans+=1
            if s[i-1]=="a" and s[i+1]=="a":
                s[i]="b"
            elif s[i-1]=="a" and s[i+1]=="b":
                s[i]="c"
            elif s[i-1]=="b" and s[i+1]=="a":
                s[i]="c"
            elif s[i-1]=="b" and s[i+1]=="b":
                s[i]="a"
            else:s[i]="a"
        if s[i]==s[i-1] and i==n-1:
            ans+=1
            s[i]= "a" if s[i-1]!="a" else "b"
    return ans

